import pandas as pd

def feature(history):
    d = history.copy()
    d['v'] = d['smart_9_raw'].astype(float)
    def _z(g):
        s = g['v']
        mu = s.mean()
        sd = s.std()
        last = float(s.iloc[-1]) if len(s) else 0.0
        if pd.isna(sd) or sd == 0:
            return 0.0
        return (last - float(mu)) / float(sd)
    return d.groupby('serial_number', group_keys=False).apply(_z)

